# 输入行列数
n, m = map(int, input().split())
# 输入每一行的海拔
h = []
for i in range(n):
    row = list(map(int, input().split()))
    h.append(row)
ans = 0
# 先遍历行
for i in range(n):
    # 再遍历列
    for j in range(m):
        ok = True
        # 遍历周边8个格子
        for k in range(-1, 2):
            for l in range(-1, 2):
                # 边界判定,不能超列表边界
                if 0 <= i + k < n and 0 <= j + l < m and h[i + k][j + l] < h[i][j]:
                    ok = False
        if(ok):
            ans += 1
print(ans)
